import * as React from "react"

function MinimalTestimonialCard({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="minimal-testimonial-card"
      className={className}
      {...props}
    >
      <blockquote className="relative w-full bg-white p-5 border border-gray-200 break-inside-avoid-column m-10">
          <h2 className="text-sm">“Laravel takes the pain out of building modern, scalable web apps.“</h2>
          <div className="mt-5 flex items-start gap-4">
              <img src="https://www.svgrepo.com/show/491978/gas-costs.svg" className="w-10 h-10 object-cover object-center" alt="Aaron Francis" />
              <div className="text-xs">
                  <cite className="not-italic">Aaron Francis</cite>
                  <p className="text-gray-700">Creator of <a href="" target="_blank" className="text-red-500">XYZ</a></p>
              </div>
          </div>
      </blockquote>
    </div>
  )
}

export { MinimalTestimonialCard }
